import {createRouter, createWebHistory} from 'vue-router';
import MyAbout from './views/About.vue';
import MyResearch from './views/Research.vue';
import MyProjects from './views/Projects.vue';
import MyCV from './views/CV.vue';
import MyInternship from './views/Internship.vue';
import MyContact from './views/Contact.vue';

const routes = [
    {'path': '/', component: MyAbout},
    {'path': '/about', component: MyAbout},
    {'path': '/research', component: MyResearch},
    {'path': '/projects', component: MyProjects},
    {'path': '/internship', component: MyInternship},
    {'path': '/cv', component: MyCV},
    {'path': '/contact', component: MyContact}
];

const router = createRouter({
    history: createWebHistory(),
    routes,
});

export default router;
