<template>
  <video
    ref="videoEl"
    class="demo-video"
    :controls="controls"
    :autoplay="autoplay"
    :loop="loop"
    :muted="muted"
    playsinline
    preload="metadata"
    @play="onPlay"
    @pause="onPause"
  >
    <source :src="src" type="video/mp4">
    Your browser does not support HTML5 video.
  </video>
</template>

<script setup>
import { ref } from 'vue';

defineProps({
  src: { type: String, required: true },
  controls: { type: Boolean, default: true },
  autoplay: { type: Boolean, default: false },
  muted: { type: Boolean, default: true },
  loop: { type: Boolean, default: false },
});

const emits = defineEmits(['play', 'pause']);
const videoEl = ref(null);

function onPlay() {
  emits('play');
}

function onPause() {
  emits('pause');
}
</script>

<style scoped>
.demo-video {
  display: block;
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
}
</style>
