<template>
  <div class="app">
    <aside
      class="sidebar"
      :class="{ 'is-open': sidebarOpen }"
      aria-label="Site navigation"
    >
      <div class="sidebar__brand">
        <h1 class="sidebar__name">Jiahao Chen</h1>
        <p>Software engineering · HCI &amp; human–AI interaction</p>
      </div>
      <ul class="nav">
        <li v-for="item in navItems" :key="item.to">
          <router-link
            :to="item.to"
            :aria-current="isNavActive(item.to) ? 'page' : undefined"
            @click="onNavClick"
          >
            {{ item.label }}
          </router-link>
        </li>
      </ul>
    </aside>

    <button
      type="button"
      class="overlay"
      :class="{ 'is-visible': sidebarOpen }"
      aria-label="Close menu"
      @click="closeMenu"
    />

    <div class="shell">
      <header class="topbar">
        <button
          type="button"
          class="menu-btn"
          :aria-expanded="sidebarOpen ? 'true' : 'false'"
          @click="toggleMenu"
        >
          Menu
        </button>
        <p class="topbar__title">{{ pageTitle }}</p>
      </header>

      <main class="main">
        <router-view />
      </main>

      <footer class="footer">© 2025 Jiahao Chen</footer>
    </div>
  </div>
</template>

<script>
const ROUTE_TITLES = {
  '/': 'About',
  '/about': 'About',
  '/research': 'Research',
  '/projects': 'Projects',
  '/internship': 'Internship',
  '/cv': 'Curriculum vitae',
  '/contact': 'Contact',
};

export default {
  name: 'App',
  data() {
    return {
      sidebarOpen: false,
      navItems: [
        { label: 'About', to: '/about' },
        { label: 'Research', to: '/research' },
        { label: 'Projects', to: '/projects' },
        { label: 'Internship', to: '/internship' },
        { label: 'CV', to: '/cv' },
        { label: 'Contact', to: '/contact' },
      ],
    };
  },
  computed: {
    pageTitle() {
      return ROUTE_TITLES[this.$route.path] ?? 'Jiahao Chen';
    },
  },
  watch: {
    $route() {
      if (typeof window !== 'undefined' && window.innerWidth <= 768) {
        this.closeMenu();
      }
    },
  },
  mounted() {
    window.addEventListener('resize', this.onResize);
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.onResize);
  },
  methods: {
    isNavActive(to) {
      const path = this.$route.path;
      if (to === '/about') return path === '/' || path === '/about';
      return path === to;
    },
    toggleMenu() {
      this.sidebarOpen = !this.sidebarOpen;
    },
    closeMenu() {
      this.sidebarOpen = false;
    },
    onNavClick() {
      if (window.innerWidth <= 768) this.closeMenu();
    },
    onResize() {
      if (window.innerWidth > 768) this.closeMenu();
    },
  },
};
</script>
